      SUBROUTINE SEPTUMCC     CALCULATES R MATRIX FOR AN ELECTROSTATIC SEPTUMC      INCLUDE 'BETAC.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM41.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'R.CIN'C      IL = IPTOJ(1)      IV = IPTOJ(2)      IAP = IPTOJ(3)      IE = IPTOJ(4)      L = DATAR(I+IL)*UNITI(8)      IF (IV .NE. 0 .AND. IAP .NE. 0) GO TO 10      IF (IE .NE. 0) GO TO 20      EFIELD = 0.0      GO TO 30C   10 VOLTS = DATAR(I+IV)*UNITI(14)      AP = DATAR(I+IAP)*UNITI(1)      EFIELD = VOLTS/AP      GO TO 30C   20 EFIELD = DATAR(I+IE)*UNITI(14)/UNITI(1)C   30 IF (NORD1 .LT. 1) GO TO 100      AL = EFIELD*L*10.0**10/(CLIGHT*RI*BETA)      B2M2 = BETA**2 - 2.0      COD(3) = 0.5*L*AL      COD(4) = AL      R(1,2) = L      R(3,4) = L      R(3,6) = 0.5*B2M2*AL*L      R(4,6) = B2M2*AL      IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2       IF (AL .NE. 0.0) THEN        DCOV = .TRUE.        IF (BAX) R1P = .TRUE.      ENDIFC  100 RETURN      END